-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): relief capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- BEGINNER
--   Fields read with the switch on: kolocreek_gas_critical_area_in2,
--   kolocreek_gas_subcritical_area_in2, kolocreek_liquid_area_in2,
--   kolocreek_steam_area_in2, kolocreek_critical_pressure_ratio,
--   kolocreek_gas_coefficient_c.
--   The PSV tab rounds areas to 3 decimals and printed neither the critical
--   ratio nor C; the prompt asks 6 decimals.
--   APPENDED: Read the figures in the Relief and Flare Studio with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- ADVANCED
--   Fields read with the switch on: gbaran_blowdown_time_s,
--   gbaran_choked_floor_psia.
--   The Blowdown tab rounds the time to 1 decimal and never showed the choked
--   floor; its engine call also ignored the flare back pressure (fixed in the
--   same Suite PR with a Flare back pressure (psia) input, default 14.7).
--   APPENDED: On the Blowdown tab, type the start and end pressures as gauge
--   pressures (each psia figure less 14.7) and the 16.5 psia flare back pressure
--   into Flare back pressure (psia). Read the figures in the Relief and Flare
--   Studio with its Full precision switch on (at the top of the page): it prints
--   them to the precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/relief.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
begin
  -- relief / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'relief' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w3 relief refused: relief/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '58514b57d30bbbe8476a9038d0317b87' and fields = '[{"key": "kolocreek_critical_pressure_ratio", "tol": 5E-7, "unit": "fraction", "label": "The critical flow pressure ratio at the stated k", "expected": 0.5439270375653221}, {"key": "kolocreek_gas_coefficient_c", "tol": 0.000001, "unit": "USC coefficient", "label": "The gas coefficient C at the stated k", "expected": 347.9129792663607}, {"key": "kolocreek_gas_critical_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required gas area against the flare header back pressure", "expected": 1.227071995812397}, {"key": "kolocreek_gas_subcritical_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required gas area against the pressured header", "expected": 1.3771233172603285}, {"key": "kolocreek_liquid_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required liquid area", "expected": 1.429643931987363}, {"key": "kolocreek_steam_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required steam area", "expected": 2.3600699760747905}]'::jsonb then 'old'
              when md5(prompt) = '3c5a58c995b83be31bb626fc7ff73543' and fields = '[{"key": "kolocreek_critical_pressure_ratio", "tol": 5E-7, "unit": "fraction", "label": "The critical flow pressure ratio at the stated k", "expected": 0.5439270375653221}, {"key": "kolocreek_gas_coefficient_c", "tol": 0.000001, "unit": "USC coefficient", "label": "The gas coefficient C at the stated k", "expected": 347.9129792663607}, {"key": "kolocreek_gas_critical_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required gas area against the flare header back pressure", "expected": 1.227071995812397}, {"key": "kolocreek_gas_subcritical_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required gas area against the pressured header", "expected": 1.3771233172603285}, {"key": "kolocreek_liquid_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required liquid area", "expected": 1.429643931987363}, {"key": "kolocreek_steam_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required steam area", "expected": 2.3600699760747905}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'relief' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w3 relief refused: relief/beginner matches neither its post-W1 form (prompt md5 58514b57d30bbbe8476a9038d0317b87) nor its W3 form (prompt md5 3c5a58c995b83be31bb626fc7ff73543), with the fields this file was generated against';
  end if;

  -- relief / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'relief' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w3 relief refused: relief/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '15e5f9f579da3569b5e104cc7c079ff8' and fields = '[{"key": "gbaran_initial_mass_lb", "tol": 0.00005, "unit": "lb", "label": "The gas inventory at the start of the blowdown", "expected": 3146.73713377691}, {"key": "gbaran_blowdown_time_s", "tol": 0.0001, "unit": "s", "label": "The time to reach the end pressure", "expected": 183.65917528878765}, {"key": "gbaran_final_temperature_degr", "tol": 0.000001, "unit": "degR", "label": "The gas temperature at the end pressure", "expected": 369.49595889955833}, {"key": "gbaran_choked_floor_psia", "tol": 5E-7, "unit": "psia", "label": "The vessel pressure below which the flow stops being choked", "expected": 29.833914945452783}, {"key": "gbaran_radiant_intensity_kwm2", "tol": 5E-7, "unit": "kW/m2", "label": "The radiant intensity at the stated distance", "expected": 1.0419219398921857}, {"key": "gbaran_setback_distance_m", "tol": 0.000001, "unit": "m", "label": "The distance at which the intensity falls to the project allowable", "expected": 52.56781758753126}]'::jsonb then 'old'
              when md5(prompt) = 'a4949eeec60ee168c7e5bb2f7273280a' and fields = '[{"key": "gbaran_initial_mass_lb", "tol": 0.00005, "unit": "lb", "label": "The gas inventory at the start of the blowdown", "expected": 3146.73713377691}, {"key": "gbaran_blowdown_time_s", "tol": 0.0001, "unit": "s", "label": "The time to reach the end pressure", "expected": 183.65917528878765}, {"key": "gbaran_final_temperature_degr", "tol": 0.000001, "unit": "degR", "label": "The gas temperature at the end pressure", "expected": 369.49595889955833}, {"key": "gbaran_choked_floor_psia", "tol": 5E-7, "unit": "psia", "label": "The vessel pressure below which the flow stops being choked", "expected": 29.833914945452783}, {"key": "gbaran_radiant_intensity_kwm2", "tol": 5E-7, "unit": "kW/m2", "label": "The radiant intensity at the stated distance", "expected": 1.0419219398921857}, {"key": "gbaran_setback_distance_m", "tol": 0.000001, "unit": "m", "label": "The distance at which the intensity falls to the project allowable", "expected": 52.56781758753126}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'relief' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w3 relief refused: relief/advanced matches neither its post-W1 form (prompt md5 15e5f9f579da3569b5e104cc7c079ff8) nor its W3 form (prompt md5 a4949eeec60ee168c7e5bb2f7273280a), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w3 relief: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 relief refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'KOLO CREEK, a gas plant with three relief cases on one train. Relieving pressures carry a 10 percent overpressure on the set pressure, and a gauge pressure becomes absolute by adding an atmosphere of 14.7 psia. THE GAS CASE: 37500 lb an hour through a conventional valve set at 385 psig, relieving at 165 degF, with a molecular weight of 23.5, a compressibility of 0.89 and a k of 1.31. The vendor states Kd 0.975, and Kb and Kc are both 1. It discharges first to a flare header at 55 psia, and then the SAME load and the SAME valve are read against a header already pressured to 330 psia. THE LIQUID CASE: 640 gpm through a valve set at 295 psig against a back pressure of 65 psig, with a specific gravity of 0.79 and no viscosity correction, because the service is taken as inviscid. The vendor states Kd 0.65, and Kw and Kc are both 1. THE STEAM CASE: 78000 lb an hour of saturated steam through a valve set at 585 psig. The vendor states Kd 0.975, and Kb, Kc and KSH are all 1. Report six values: the critical flow pressure ratio at the stated k, the gas coefficient C, the required gas area against the 55 psia header, the required gas area against the 330 psia header, the required liquid area and the required steam area. The ratio as a fraction, C as a number and every area in square inches, all to six decimals. Read the figures in the Relief and Flare Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'relief' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 relief refused: relief/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '3c5a58c995b83be31bb626fc7ff73543' and fields = '[{"key": "kolocreek_critical_pressure_ratio", "tol": 5E-7, "unit": "fraction", "label": "The critical flow pressure ratio at the stated k", "expected": 0.5439270375653221}, {"key": "kolocreek_gas_coefficient_c", "tol": 0.000001, "unit": "USC coefficient", "label": "The gas coefficient C at the stated k", "expected": 347.9129792663607}, {"key": "kolocreek_gas_critical_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required gas area against the flare header back pressure", "expected": 1.227071995812397}, {"key": "kolocreek_gas_subcritical_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required gas area against the pressured header", "expected": 1.3771233172603285}, {"key": "kolocreek_liquid_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required liquid area", "expected": 1.429643931987363}, {"key": "kolocreek_steam_area_in2", "tol": 0.000001, "unit": "in2", "label": "The required steam area", "expected": 2.3600699760747905}]'::jsonb) from public.academy_capstones where app_slug = 'relief' and tier = 'beginner' and active) is not true then
    raise exception 'w3 relief refused: relief/beginner does not read back as its W3 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'GBARAN, a compression station. A vessel of 640 cubic feet holds gas at 1185 psia and 555 degR, with a molecular weight of 21.5, a k of 1.26 and a compressibility of 0.87 held constant throughout. The universal gas constant is 1545.349 ft lbf per lbmol degR. It depressures to 165 psia through an orifice of 1.375 inch diameter with a discharge coefficient of 0.84, against a flare back pressure of 16.5 psia. The gas in the vessel expands isentropically and the flow is taken as choked throughout, on the gas coefficient C at the stated k. The studio marches this at a time step of 0.1 s. The flare it discharges to releases 742000 kW, with a radiated fraction of 0.27 and a transmissivity of 0.91, read as a point source 118 m away. The project allowable is 5.25 kW per m2. Report six values: the gas inventory at the start in lb, the time to reach 165 psia in seconds, the gas temperature at 165 psia in degR, the vessel pressure below which the flow stops being choked in psia, the radiant intensity at 118 m in kW per m2, and the distance at which the intensity falls to the project allowable in m. The inventory to four decimals. Everything else to six decimals. On the Blowdown tab, type the start and end pressures as gauge pressures (each psia figure less 14.7) and the 16.5 psia flare back pressure into Flare back pressure (psia). Read the figures in the Relief and Flare Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'relief' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 relief refused: relief/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'a4949eeec60ee168c7e5bb2f7273280a' and fields = '[{"key": "gbaran_initial_mass_lb", "tol": 0.00005, "unit": "lb", "label": "The gas inventory at the start of the blowdown", "expected": 3146.73713377691}, {"key": "gbaran_blowdown_time_s", "tol": 0.0001, "unit": "s", "label": "The time to reach the end pressure", "expected": 183.65917528878765}, {"key": "gbaran_final_temperature_degr", "tol": 0.000001, "unit": "degR", "label": "The gas temperature at the end pressure", "expected": 369.49595889955833}, {"key": "gbaran_choked_floor_psia", "tol": 5E-7, "unit": "psia", "label": "The vessel pressure below which the flow stops being choked", "expected": 29.833914945452783}, {"key": "gbaran_radiant_intensity_kwm2", "tol": 5E-7, "unit": "kW/m2", "label": "The radiant intensity at the stated distance", "expected": 1.0419219398921857}, {"key": "gbaran_setback_distance_m", "tol": 0.000001, "unit": "m", "label": "The distance at which the intensity falls to the project allowable", "expected": 52.56781758753126}]'::jsonb) from public.academy_capstones where app_slug = 'relief' and tier = 'advanced' and active) is not true then
    raise exception 'w3 relief refused: relief/advanced does not read back as its W3 form';
  end if;

  raise notice 'w3 relief: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
